function nazwaMiesiaca(numer) {
  switch (numer) {
    case 1: return "styczen";
    case 2: return "luty";
    case 3: return "marzec";
    case 4: return "kwiecien";
    case 5: return "maj";
    case 6: return "czerwiec";
    case 7: return "lipiec";
    case 8: return "sierpien";
    case 9: return "wrzesien";
    case 10: return "pazdziernik";
    case 11: return "listopad";
    case 12: return "grudzien";
  }
}

console.log(nazwaMiesiaca(6)); // "czerwiec"

function typDnia(dzien) {
  switch (dzien) {
    case "sobota":
    case "niedziela":
      return "weekend";
    default:
      return "dzien roboczy";
  }
}

console.log(typDnia("sobota")); // "weekend"
console.log(typDnia("wtorek")); // "dzien roboczy"

function ocenaSlownie(ocena) {
  switch (ocena) {
    case 1: return "niedostateczny";
    case 2: return "dopuszczajacy";
    case 3: return "dostateczny";
    case 4: return "dobry";
    case 5: return "bardzo dobry";
    case 6: return "celujacy";
    default: return "nieznana ocena";
  }
}

console.log(ocenaSlownie(5)); // "bardzo dobry"

function nazwaMiesiaca(numer) {
  switch (numer) {
    case 1: return "styczen";
    case 2: return "luty";
    case 12: return "grudzien";
    default: return "nieznany miesiac";
  }
}

console.log(nazwaMiesiaca(13)); // "nieznany miesiac"

const NAZWY_MIESIECY = { 1: "styczen", 2: "luty", 12: "grudzien" };

function nazwaMiesiaca(numer) {
  return NAZWY_MIESIECY[numer] ?? "nieznany miesiac";
}

console.log(nazwaMiesiaca(2));  // "luty"
console.log(nazwaMiesiaca(99)); // "nieznany miesiac"

const KOLORY_STATUSU = {
  aktywny: "zielony",
  wstrzymany: "zolty",
  zakonczony: "czerwony"
};

function kolorStatusu(status) {
  return KOLORY_STATUSU[status] ?? "szary";
}

console.log(kolorStatusu("aktywny")); // "zielony"
console.log(kolorStatusu("nieznany")); // "szary"

const OPERACJE = {
  dodaj: (a, b) => a + b,
  odejmij: (a, b) => a - b,
  mnoz: (a, b) => a * b
};

function wykonajOperacje(nazwa, a, b) {
  return OPERACJE[nazwa](a, b);
}

console.log(wykonajOperacje("dodaj", 5, 3)); // 8
console.log(wykonajOperacje("mnoz", 5, 3));  // 15

